// Netlify Edge Function: /sitemap.xml is generated by the Rails API, which knows
// every public event, venue, organizer and collection. The API origin comes from
// HAFAPASS_API_ORIGIN so no host is hardcoded in _redirects.
import { apiOrigin } from '../shared/apiOrigin.js'

export default async () => {
  const origin = apiOrigin()
  // Never let the SPA fallback answer /sitemap.xml with index.html.
  if (!origin) return new Response('Sitemap is not configured.\n', { status: 404, headers: { 'content-type': 'text/plain; charset=utf-8' } })

  try {
    const response = await fetch(`${origin}/sitemap.xml`, { headers: { accept: 'application/xml' } })
    if (!response.ok) return new Response('Sitemap is temporarily unavailable.\n', { status: 502, headers: { 'content-type': 'text/plain; charset=utf-8' } })
    return new Response(await response.text(), {
      status: 200,
      headers: { 'content-type': 'application/xml; charset=utf-8', 'cache-control': 'public, max-age=3600' },
    })
  } catch {
    return new Response('Sitemap is temporarily unavailable.\n', { status: 502, headers: { 'content-type': 'text/plain; charset=utf-8' } })
  }
}

export const config = {
  path: '/sitemap.xml',
}
